import events from './events.json' with {type:'json'};

const MIN_PAGE_SIZE = 1;
const MAX_PAGE_SIZE = 3;
const DEFAULT_PAGE_SIZE = 2;

function encodeCursor(index) {
  return Buffer.from(JSON.stringify({i:index})).toString('base64url');
}

function decodeCursor(cursor) {
  let parsed;
  try {
    parsed = JSON.parse(Buffer.from(cursor, 'base64url').toString('utf8'));
  } catch {
    throw new Error('Unknown cursor');
  }
  if (!parsed || typeof parsed !== 'object' || typeof parsed.i !== 'number' || !Number.isInteger(parsed.i) || parsed.i < 0 || parsed.i >= events.length) {
    throw new Error('Unknown cursor');
  }
  return parsed.i;
}

export async function listTools() {
  return [{
    name: 'events_list',
    description: 'List events with pagination',
    inputSchema: {
      type: 'object',
      properties: {
        cursor: { type: 'string' },
        page_size: { type: 'integer', minimum: 1, maximum: 3 }
      }
    }
  }];
}

export async function callTool(name, args) {
  if (name !== 'events_list') {
    throw new Error('Unknown tool: ' + name);
  }
  // validate args is object
  if (args === null || typeof args !== 'object' || Array.isArray(args)) {
    throw new Error('Invalid arguments');
  }
  const keys = Object.keys(args);
  for (const k of keys) {
    if (k !== 'cursor' && k !== 'page_size') {
      throw new Error('Unknown field: ' + k);
    }
  }
  let page_size = DEFAULT_PAGE_SIZE;
  if ('page_size' in args) {
    page_size = args.page_size;
    if (!Number.isInteger(page_size) || page_size < MIN_PAGE_SIZE || page_size > MAX_PAGE_SIZE) {
      throw new Error('page_size must be an integer from 1 to 3');
    }
  }
  let start = 0;
  if ('cursor' in args) {
    const cursor = args.cursor;
    if (typeof cursor !== 'string') {
      throw new Error('cursor must be a string');
    }
    start = decodeCursor(cursor);
  }
  const slice = events.slice(start, start + page_size);
  const result = { events: slice };
  if (start + page_size < events.length) {
    result.next_cursor = encodeCursor(start + page_size);
  }
  return { content: [{ type: 'text', text: JSON.stringify(result) }] };
}
